import {D} from './dialogues.js';
import {FourthEncounters} from './encounters.js';
import {WAREHOUSE,CONTROL,RUNNER_GATE_SECONDS} from './missions.js';
import {distance,position} from './world.js';
export class FourthActions{
 constructor(rt){this.rt=rt;this.encounters=new FourthEncounters(this);}
 get api(){return this.rt.api;}
 near(o,range=3.5){return this.rt.area()===o.area&&distance(this.rt.position(),this.rt.point(o))<range&&!this.api.get().driving&&Math.abs(this.api.get().position[1]-.2-this.rt.world.floor(o.area,this.rt.point(o)))<1.5;}
 begin(o,p){const rt=this.rt,w=rt.state().world;rt.world.clearEnemies();rt.world.runner.enabled=false;for(const e of rt.world.students)e.enabled=false;if(o.speaker)rt.world.contact(o.speaker,rt.point(o),o.area);if(o.type==='dismiss')for(let i=0;i<rt.world.students.length;i++){const e=rt.world.students[i];e.enabled=true;rt.world.place(e,[-198+i*1.8,402-i%2*2]);}if(o.type==='path'||o.type==='lure'){p.pathIndex??=w.pathCheckpoints?.[o.id]||0;p.branch??=w.pathBranches?.[o.id];}
  if(o.type==='lure'&&!o.encounter){const restoring=!!p.enemies,route=this.route(o,p),base=route[Math.max(0,p.pathIndex-1)];rt.world.spawn([[base[0]-4,base[1]-5,'brawler'],[base[0]+4,base[1]-8,'charger'],[base[0],base[1]-12,'guard']],p);if(!restoring)for(const e of rt.world.enemies)e.routeIndex=Math.max(0,p.pathIndex-2);}
  if(['tail','runner'].includes(o.type)){p.pathIndex??=w.pathCheckpoints?.[o.id]||(o.type==='tail'?1:0);const route=this.route(o,p),at=p.actorAt||route[Math.min(p.pathIndex,route.length-1)];rt.world.runner.enabled=true;rt.world.runner.hp=p.targetHP??100;rt.world.runner.c2=false;rt.world.place(rt.world.runner,at,o.area);p.grace??=5;}
  if(o.type==='runner'&&!p.gateTime)w.opened.runnerGate=true;
  if(o.type==='upload'){p.fileHP??=180;p.upload??=0;p.wave??=0;p.waveTime??=0;p.started??=false;}
  if(o.type==='fight'&&p.spawned&&!o.encounter)rt.world.spawn(this.enemyPoints(o),p,o.area);
  if(o.type==='secure'){const r=this.api.interiors.c4_ifs_parking;rt.world.van.enabled=true;rt.world.van.g.position.set(r.ox,-4.5,17);rt.world.van.g.rotation.y=0;if(p.spawned&&!o.encounter)rt.world.spawn(this.enemyPoints(o),p,o.area);}
  for(const [ids,name,at]of[[['c401-dismiss'],'田博',[-200,404]],[['c402-race'],'练练',[4,4]],[['c402-bar'],'阿岚',[4,4]],[['c402-bar'],'练练',[4,6]],[['c402-back'],'练练',[-218,-511]],[['c402-pool'],'台球老板',[-3,0]],[['c402-pool'],'练练',[2,0]],[['c402-table'],'牌馆老板',[4,4]],[['c402-table'],'练练',[-4,4]],[['c406-song'],'练练',[4,3]],[['c406-breaker','c406-warehouse'],'练练',[-4,7]],[['c407-reveal'],'田博',[3,-362]],[['c407-reveal'],'练练',[-3,-365]]])if(ids.includes(o.id))rt.world.contact(name,o.local?[(this.api.interiors[o.area]?.ox||0)+at[0],at[1]]:at,o.area);
  this.encounters.begin(o,p);
 }
 enemyPoints(o){let points=o.enemies.map(([x,z,role])=>[(o.local?this.api.interiors[o.area].ox:0)+x,z,role]);if(o.area===WAREHOUSE&&this.rt.state().world.warehouseHelp)points=points.slice(0,2);return points;}
 route(o,p){return(p.branch==='west'?[[0,40],[-90,40],[-90,-105],[-90,-260],[-80,-260],[-80,-325],[-75,-325],[-15,-325]]:o.route).map(at=>[(o.local?this.api.interiors[o.area].ox:0)+at[0],at[1]]);}
 checkpoint(o,p){const rt=this.rt;rt.state().world.pathCheckpoints||={};rt.state().world.pathCheckpoints[o.id]=p.pathIndex;if(p.branch){rt.state().world.pathBranches||={};rt.state().world.pathBranches[o.id]=p.branch;}rt.manager.record.checkpoint=this.api.checkpoint();rt.parent.save();}
 tick(o,p,dt){const rt=this.rt,g=this.api.get(),w=rt.state().world;
  if(o.id==='c405-fight')p.escortHurtCooldown=Math.max(0,(p.escortHurtCooldown||0)-dt);
  if(o.encounter||o.type==='upload'){const result=this.encounters.tick(o,p,dt);if(result!==null)return result;}
  if(o.id==='c405-fight'&&(p.escortHP??140)<=0)return{fail:'田博被围住了。重试，别只顾着追远处的人。'};
  if(o.type==='park')return this.near(o,o.radius||20);
  if(o.type==='path'||o.type==='lure'){if(g.driving||rt.area()!==o.area)return false;let route=this.route(o,p);if(o.type==='lure'&&!p.branch&&[5,6].includes(p.pathIndex)&&g.position[0]<-45){p.branch='west';p.pathIndex=1;route=this.route(o,p);this.checkpoint(o,p);}if(p.pathIndex<route.length&&distance(rt.position(),route[p.pathIndex])<5){p.pathIndex++;this.checkpoint(o,p);}return p.pathIndex>=route.length;}
  if(o.type==='talk'||o.type==='inspect')return!!p.interacted;
  if(o.type==='dismiss'){if(this.near(o,13)){p.time=(p.time||0)+dt;for(const e of rt.world.students){e.intentX=1.1;e.intentZ=1.1;}}else for(const e of rt.world.students)e.intentX=e.intentZ=0;return(p.time||0)>=o.seconds;}
  if(o.type==='outfit'&&g.interior===o.area&&!p.entered){p.entered=true;rt.say('c403:inside-uniqlo',D.tryShirt,'面对面');rt.parent.save();return false;}
  if(o.type==='outfit')return g.interior===o.area&&!!this.api.lifeState()?.wardrobe.equipped?.startsWith('c4_');
  if(o.type==='game'&&o.brief&&!p.briefed&&this.near(o,18)){p.briefed=true;rt.say(o.id+':action',D[o.brief],'面对面');rt.parent.save();return false;}
  if(o.type==='game'||o.type==='drink')return!!p.facilityDone;
  if(o.type==='account')return g.interior===o.area&&this.api.leisureState().account.opened;
  if(o.type==='quotes')return!!p.compared;
  if(o.type==='copy'){if(p.copying){if(!this.near(o,3)){p.copying=false;p.copyTime=0;}else p.copyTime=(p.copyTime||0)+dt;}return(p.copyTime||0)>=o.seconds;}
  if(o.type==='fight'||o.type==='secure'){if(rt.area()!==o.area)return false;if(!p.spawned&&this.near(o,24)){rt.world.spawn(this.enemyPoints(o),p,o.area);if(o.id==='c405-fight')this.encounters.tianBo.markEnemies(o,p);}rt.world.preserve(p);const clear=p.spawned&&rt.world.enemies.every(e=>e.hp<=0);return o.type==='secure'?clear&&!!p.interacted:clear;}
  if(o.type==='tail'){if(rt.area()!==o.area)return false;p.grace=Math.max(0,p.grace-dt);const d=distance(rt.position(),position(rt.world.runner));p.lost=d>100&&p.grace<=0?(p.lost||0)+dt:0;if(p.lost>12)return{fail:'拿蓝袋的人跑远了 · T 从这段后巷重来'};return p.pathIndex>=this.route(o,p).length&&d<12&&!g.driving||!!p.intercepted;}
  if(o.type==='runner'){if(rt.area()!==o.area)return false;if(p.intercepted)return true;const d=distance(rt.position(),position(rt.world.runner));p.lost=d>75?(p.lost||0)+dt:0;if(p.lost>12)return{fail:'拿蓝袋的人离开视线 · T 从地下入口重来'};return false;}
  if(o.type==='relays')return['relay-left','relay-right'].every(id=>w.opened[id]||w.damage[id]===0);
  if(o.type==='upload'){if(p.fileHP<=0)return{fail:'服务器被砸停了 · T 从调度室重新接线'};if(!p.started||rt.area()!==CONTROL)return false;p.waveTime+=dt;const blocked=rt.world.enemies.some(e=>e.hp>0&&distance(position(e),rt.point(o))<3);if(!blocked&&distance(rt.position(),rt.point(o))<28)p.upload+=dt;const threshold=(p.wave+1)*8;if(p.wave<2&&p.waveTime>=threshold&&rt.world.enemies.filter(e=>e.hp>0).length<=3){p.wave++;rt.world.reinforce(this.uploadEnemies(),p,CONTROL);rt.parent.save();}rt.world.preserve(p);return p.upload>=o.seconds-(w.musicHelp||0);}return false;
 }
 uploadEnemies(){const r=this.api.interiors[CONTROL];return[[r.ox-6,8,'charger'],[r.ox+6,8,'guard'],[r.ox,9,'heavy']];}
 interact(o,p){if(!o)return false;const rt=this.rt,w=rt.state().world;if((o.encounter||o.type==='upload')&&this.encounters.interact(o,p))return true;if(['talk','inspect'].includes(o.type)&&this.near(o)){p.interacted=true;return true;}if(o.type==='copy'&&this.near(o)){p.copying=true;p.copyTime??=0;this.api.toast('开始复制 · 留在终端旁，移动或受伤会打断');return true;}if(o.type==='relays'){const box=rt.world.nearest(['relay-left','relay-right'].filter(id=>!w.opened[id]&&w.damage[id]!==0));if(box){w.opened[box.id]=true;w.damage[box.id]=0;this.api.impactSound('furniture');rt.world.apply();return true;}}if(o.type==='upload'&&this.near(o)){if(!p.started){p.started=true;p.waveTime=0;p.fileHP??=180;rt.world.spawn(this.uploadEnemies(),p,CONTROL);}return true;}if(o.type==='secure'&&this.near(o,5)){if(!p.spawned||rt.world.enemies.some(e=>e.hp>0))this.api.toast('先打退后箱旁的保全，别背对着他们开箱');else{p.interacted=true;this.api.carry('电子总账');}return true;}if(['tail','runner'].includes(o.type)){if(o.type==='runner'&&rt.world.nearest(['gate-switch'])){w.opened.runnerGate=!w.opened.runnerGate;p.gateTime=w.opened.runnerGate?0:RUNNER_GATE_SECONDS;p.gateUsed=true;rt.world.apply();this.api.toast(w.opened.runnerGate?'前方闸门已升起':'前方闸门已落下 · 30 秒后升起，快追上他');return true;}if(rt.area()===o.area&&distance(rt.position(),position(rt.world.runner))<3.4){if(!rt.world.canReach(rt.world.runner)||!rt.world.lineClear(rt.position(),position(rt.world.runner))){this.api.toast('隔着墙还够不着他，先绕过来。');return true;}p.intercepted=true;this.api.carry('蓝袋校验卡');return true;}}return false;}
 move(o,p,dt){const rt=this.rt,g=this.api.get();if(rt.area()!==o.area||g.driving){for(const e of rt.world.enemies)e.intentX=e.intentZ=0;rt.world.runner.intentX=rt.world.runner.intentZ=0;return;}const route=this.route(o,p);
  if(o.type==='lure'&&o.encounter)return;
  if(o.type==='lure'){for(const e of rt.world.enemies){e.routeIndex??=Math.max(0,p.pathIndex-2);const at=position(e);while(e.routeIndex<Math.min(p.pathIndex,route.length)&&distance(at,route[e.routeIndex])<2.5)e.routeIndex++;const aim=e.routeIndex<p.pathIndex?route[e.routeIndex]:rt.position(),d=distance(at,aim),speed=rt.world.region.canDrive(...at)?6.4:10.2;e.intentX=(aim[0]-at[0])/Math.max(.01,d)*Math.min(speed,d/dt);e.intentZ=(aim[1]-at[1])/Math.max(.01,d)*Math.min(speed,d/dt);e.g.rotation.y=Math.atan2(e.intentX,e.intentZ);e.hitCooldown=Math.max(0,(e.hitCooldown||0)-dt);if(e.windup>0){e.windup=Math.max(0,e.windup-dt);e.intentX=e.intentZ=0;e.roleMark.visible=true;if(!e.windup){if(distance(at,rt.position())<2.2)this.api.hurt(8,'跟踪者推搡');e.hitCooldown=2.4;e.roleMark.visible=false;}}else if(distance(at,rt.position())<2.2&&e.hitCooldown<=0){e.windup=.55;e.roleMark.visible=true;}}rt.world.preserve(p);return;}
  const e=rt.world.runner,at=position(e);e.intentX=e.intentZ=0;if(e.hp<=0)return;while(p.pathIndex<route.length&&distance(at,route[p.pathIndex])<1.8){p.pathIndex++;if(o.type==='tail'&&distance(rt.position(),at)<35)this.checkpoint(o,p);}if(p.intercepted)return;
  if(o.type==='runner'&&p.gateTime>0){p.gateTime=Math.max(0,p.gateTime-dt);if(!p.gateTime){rt.state().world.opened.runnerGate=true;rt.world.apply();}}const aim=route[p.pathIndex];if(aim){const d=distance(at,aim),speed=o.type==='runner'?8.2:8.3;e.intentX=(aim[0]-at[0])/Math.max(.01,d)*Math.min(speed,d/dt);e.intentZ=(aim[1]-at[1])/Math.max(.01,d)*Math.min(speed,d/dt);e.g.rotation.y=Math.atan2(e.intentX,e.intentZ);}p.actorAt=at;p.targetHP=e.hp;
 }
 event(type,data,o,p){this.encounters.event(type,data,o,p);const w=this.rt.state().world;if(type==='leisureFinish'&&o.type==='game'&&data.room===o.area&&data.type===o.game&&!data.abandoned){p.facilityDone=true;if(o.game==='karaoke')w.musicHelp=Math.min(5,Math.floor(data.hits/6));if(o.id==='c406-breaker'){w.warehouseOpen=true;w.warehouseHelp=data.score>=6;}this.rt.parent.save();}if(type==='leisureDrink'&&o.type==='drink'&&data.room===o.area){p.facilityDone=true;this.rt.parent.save();}if(type==='stockView'&&o.type==='quotes'){p.stocks||=[];if(['river_drinks','star_leisure'].includes(data.stock)&&!p.stocks.includes(data.stock))p.stocks.push(data.stock);if(p.stocks.length===2&&!p.compared){p.compared=true;this.rt.market('sync');}this.rt.parent.save();}}
 sponsor(type,room){const rt=this.rt,o=rt.manager?.objective,p=rt.manager?.record?.progress;return!!(rt.active&&!this.api.get().mapTest&&rt.manager.record?.status==='active'&&o?.sponsored&&room===o.area&&!p.facilityDone&&(o.requiredGame===type||o.game===type));}
 callReinforcements(e){this.encounters.call(e);}
 finish(o,p){if(['tail','runner'].includes(o.type))this.rt.world.runner.enabled=false;if(o.type==='lure')this.rt.state().world.chaseFinished=true;if(['tail','runner'].includes(o.type)&&p.intercepted)this.rt.state().world.calibrationCard=true;if(o.id==='c404-office')this.rt.state().world.informationCut=true;if(o.id==='c407-reveal')this.api.carry(null);}
 destination(o,p){let at=this.rt.point(o),label=o.text;if(o.requiredGame&&!p.facilityDone){const station=this.api.interiors[o.area]?.leisureStations?.find(s=>s.kind===o.requiredGame);if(station)at=station.at;}if(o.type==='path'||o.type==='lure')at=this.route(o,p)[Math.min(p.pathIndex||0,this.route(o,p).length-1)];if(o.encounter==='escort'&&p.activeWave!=null){const ally=this.rt.world.contacts.get('田博');if(ally)at=position(ally);label='保护田博 · 打退当前拦截';}if(['tail','runner'].includes(o.type)&&this.rt.world.runner.enabled)at=position(this.rt.world.runner);if(o.encounter==='runner'&&!p.gateUsed){const box=this.rt.world.props.get('gate-switch');if(distance(this.rt.position(),box.at)<18){at=box.at;label='货梯旁的开关 · E 提前落闸';}}if(o.type==='secure'&&o.encounter==='parking')at=position(this.rt.world.van);if(o.type==='relays'){const w=this.rt.state().world,id=['relay-left','relay-right'].find(id=>!w.opened[id]&&w.damage[id]!==0);if(id)at=[this.rt.world.props.get(id).at[0]+(id==='relay-left'?1.5:-1.5),-1];}return{at,area:o.area,label};}
 prompt(o,p){if(!o)return'';const extra=(o.encounter||o.type==='upload')&&this.encounters.prompt(o,p);if(extra)return extra;const near=this.near(o);if(['talk','inspect'].includes(o.type)&&near)return o.speaker?'E · 与'+o.speaker+'交谈':'E · '+(this.rt.world.props.get(o.prop)?.name||'查看');if(o.type==='copy'&&near)return'E · 复制记录';if(o.type==='upload'&&near)return p.started?'保护服务器 · 上传中':'E · 启动上传';if(o.type==='relays'&&this.rt.world.nearest(['relay-left','relay-right']))return'E · 拔干扰接线 / F 砸箱';if(o.type==='secure'&&this.near(o,5))return'E · 取电子总账';if(o.type==='runner'&&this.rt.world.nearest(['gate-switch']))return'E · 检修闸开关';if(['tail','runner'].includes(o.type)&&this.rt.area()===o.area&&distance(this.rt.position(),position(this.rt.world.runner))<3.4&&this.rt.world.canReach(this.rt.world.runner)&&this.rt.world.lineClear(this.rt.position(),position(this.rt.world.runner)))return'E · 截住拿蓝袋的人';return'';}
 hint(o,p){if(o.type==='park')return this.api.get().driving?' · 到目标区域后 E 下车，自动完成':' · 步行到达目标区域，自动完成';if(o.requiredGame&&!p.facilityDone)return' · '+({race:'先完成赛车掩护',drink:'先在吧台碰杯',mahjong:'先陪收钱的人打完这局',billiards:'陪老板打完一局，进球多少都可以',karaoke:'后场突围后唱一段',breaker:'处理电箱，再玩完街机等钥匙'}[o.requiredGame]);if(o.encounter==='runner'&&p.gateTime>0)return' · 闸门已关 '+Math.ceil(p.gateTime)+' 秒后升起';const extra=this.encounters.hint(o,p);if(extra)return extra;if(o.type==='copy')return' · '+Math.min(o.seconds,p.copyTime||0).toFixed(1)+'/'+o.seconds+' 秒';if(o.type==='upload')return' · 上传 '+Math.floor(p.upload||0)+' 秒 / 服务器 '+Math.ceil(p.fileHP??180);if(['fight','secure'].includes(o.type)&&p.spawned)return' · 剩 '+this.rt.world.enemies.filter(e=>e.hp>0).length+' 人';if(o.type==='game')return' · 完成即可，无需获胜';return'';}
}
